// main/rg/rg_sound_data.h -- Release Guidance key sounds (24 kHz mono PCM16 in Flash).
// Data is generated by tools/release_guidance/gen_assets.py; no ESP-IDF dependency.
#pragma once

#include <stdint.h>

#define RG_SOUND_RATE_HZ 24000

typedef enum {
    RG_SOUND_BANK_DROPLET = 0,   // A: water drop
    RG_SOUND_BANK_BELL,          // B: wind chime
    RG_SOUND_BANK_MARIMBA,       // C: marimba
    RG_SOUND_BANK_COUNT
} rg_sound_bank_t;

typedef enum {
    RG_SOUND_TAP = 0,            // page turn / focus change: one note
    RG_SOUND_CONFIRM,            // OK confirm: two rising notes
    RG_SOUND_KIND_COUNT
} rg_sound_kind_t;

typedef struct {
    const int16_t *pcm;
    uint32_t samples;
} rg_sound_clip_t;

extern const rg_sound_clip_t RG_SOUND_CLIPS[RG_SOUND_BANK_COUNT][RG_SOUND_KIND_COUNT];
